class Solution {
    int atMost(const vector<int>& nums, int bound) {
        int ans = 0, cur = 0;
        for (int x : nums) {
            cur = (x <= bound) ? cur + 1 : 0;
            ans += cur;
        }
        return ans;
    }
public:
